"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[68326],{68326:function(t){t.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/509aebf0ba3ad77b392038c7b8664335.jpg\\"\\n  title=\\"Hyatt Centric Melbourne\\"\\n  cuisine=\\"Hotel\\"\\n  address=\\"25 Downie St, Melbourne VIC 3000 Australia\\"\\n  rating=3.5\\n  tags=\\"spot\\"\\n/>\\n</center>\\n\\n## Review\\nThis was the hotel I stayed at during my Melbourne trip.  \\nI stayed in the standard ```King Bed``` room, and the overall condition was very clean and comfortable — I was pleased with it.  \\n\\nTrue to the Hyatt brand, the sleek modern interior and tidy hygiene standards stood out.  \\nThe only slightly disappointing part was that the bathroom didn\'t have a <mark>bidet</mark>.  \\n\\nEven so, the hotel\'s proximity to Melbourne\'s CBD made it excellent in terms of <mark>accessibility</mark>.  \\nGetting to major attractions and tram stops was very convenient, and the surrounding infrastructure was well-developed.  \\nAbove all, being able to book at a relatively ```affordable price``` compared to other 5-star hotels made it a stay that delivered both great value and satisfaction.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/509aebf0ba3ad77b392038c7b8664335.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Hyatt Centric Melbourne\\">\\n<img src=\\"/assets/snippets/location/2298f2b8011b0f1a39446b4d2c9e15d5.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Hyatt Centric Melbourne\\">\\n<img src=\\"/assets/snippets/location/fd0132aa24e120e4e048f630b09d82c2.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Hyatt Centric Melbourne\\">\\n<img src=\\"/assets/snippets/location/8b1113abf8e74c03ee93b6f9c7db69fd.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Hyatt Centric Melbourne\\">\\n<img src=\\"/assets/snippets/location/0fddc0c1251d1981a6cc4cb8e639d8f1.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Hyatt Centric Melbourne\\">\\n<img src=\\"/assets/snippets/location/2bd1c828e581d168abb2f8760517da3b.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Hyatt Centric Melbourne\\">\\n</pictures>\\n"}')}}]);